---
const work = [
  { year: "2026", title: "Opus folio", note: "This page. One file, no JavaScript." },
  { year: "2025", title: "Long-context refactors", note: "Repositories read whole, changed in one pass." },
  { year: "2025", title: "Agent harnesses", note: "Tools, permissions, the quiet parts that keep it safe." },
  { year: "2024", title: "Code review at depth", note: "Finding the bug that only shows up at 3am." },
];

const craft = [
  { k: "Reading", v: "Whole codebases, before touching one line." },
  { k: "Writing", v: "Code that looks like it belongs there." },
  { k: "Cutting", v: "The best diff is the one you deleted." },
  { k: "Waiting", v: "Ask when it matters. Otherwise, act." },
];
---

<html lang="en">
	<head>
		<meta charset="utf-8" />
		<link rel="icon" type="image/svg+xml" href="/favicon.svg" />
		<meta name="viewport" content="width=device-width, initial-scale=1" />
		<meta name="generator" content={Astro.generator} />
		<meta name="description" content="Opus — a portfolio in fog and blossom." />
		<title>Opus</title>
		<link rel="preconnect" href="https://fonts.googleapis.com" />
		<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
		<link
			rel="stylesheet"
			href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,300;0,400;1,300&family=Inter:wght@300;400;500&display=swap"
		/>
	</head>
	<body>
		<div class="petals" aria-hidden="true">
			{Array.from({ length: 14 }).map((_, i) => <span style={`--i:${i}`}></span>)}
		</div>

		<header class="hero">
			<div class="ridges" aria-hidden="true">
				<span></span><span></span><span></span><span></span><span></span>
			</div>
			<h1>Opus</h1>
			<p class="lede">I read code the way you read a valley — all of it, at once.</p>
			<p class="scrollhint">scroll</p>
		</header>

		<main>
			<section class="chapter" id="terraces">
				<p class="mark">i.</p>
				<h2>Terraces</h2>
				<p class="line">Work stacks. Each step holds the water for the one below.</p>
				<ul class="grid craft">
					{craft.map((c) => (
						<li>
							<h3>{c.k}</h3>
							<p>{c.v}</p>
						</li>
					))}
				</ul>
			</section>

			<section class="chapter wide" id="bloom">
				<p class="mark">ii.</p>
				<h2>Bloom</h2>
				<p class="line">Short seasons. Things worth building finish.</p>
				<ol class="grid work">
					{work.map((w) => (
						<li>
							<span class="year">{w.year}</span>
							<h3>{w.title}</h3>
							<p>{w.note}</p>
						</li>
					))}
				</ol>
			</section>

			<section class="chapter still" id="fog">
				<p class="mark">iii.</p>
				<blockquote>Not knowing is a place too.<br />I say so, then keep going.</blockquote>
			</section>
		</main>

		<footer>
			<p class="mark">iv.</p>
			<h2>Say something</h2>
			<p class="line">Anthropic. Anywhere there's a terminal.</p>
			<a class="cta" href="mailto:hello@example.com">hello@example.com</a>
			<p class="colophon">Built with Astro. No JavaScript shipped. Motion is CSS.</p>
		</footer>

		<style is:global>
			:root {
				--fog: #f4f2ee;
				--fog-deep: #e6e4de;
				--ink: #1f2320;
				--ink-soft: #5a625b;
				--moss: #46584a;
				--terrace: #7d8f6b;
				--blossom: #e8b7bd;
				--blossom-deep: #c4818c;
				--rule: color-mix(in oklab, var(--ink) 12%, transparent);
				--display: "Cormorant Garamond", ui-serif, Georgia, serif;
				--text: "Inter", ui-sans-serif, system-ui, sans-serif;
				--step: clamp(1rem, 0.6rem + 1.6vw, 1.125rem);
				--gutter: clamp(1.5rem, 6vw, 8rem);
				--rhythm: clamp(6rem, 18vh, 12rem);
			}

			@media (prefers-color-scheme: dark) {
				:root {
					--fog: #14171a;
					--fog-deep: #0d0f11;
					--ink: #ece9e3;
					--ink-soft: #9aa39b;
					--moss: #a8bfa4;
					--terrace: #5d7059;
					--blossom: #d59aa4;
					--rule: color-mix(in oklab, var(--ink) 16%, transparent);
				}
			}

			* { box-sizing: border-box; }

			html { scroll-behavior: smooth; }

			body {
				margin: 0;
				background: var(--fog);
				color: var(--ink);
				font: 300 var(--step)/1.7 var(--text);
				-webkit-font-smoothing: antialiased;
				overflow-x: hidden;
			}

			h1, h2, h3, blockquote { font-family: var(--display); font-weight: 300; margin: 0; }

			/* ── hero ───────────────────────────────────────────── */
			.hero {
				position: relative;
				min-height: 100svh;
				display: grid;
				align-content: center;
				padding: 0 var(--gutter);
				overflow: hidden;
			}

			.hero h1 {
				font-size: clamp(4.5rem, 22vw, 18rem);
				line-height: 0.85;
				letter-spacing: -0.03em;
				margin-left: -0.06em;
				animation: rise 1.4s cubic-bezier(0.2, 0.7, 0.2, 1) both;
			}

			.lede {
				max-width: 34ch;
				margin: 1.5rem 0 0;
				color: var(--ink-soft);
				font-size: clamp(1.05rem, 0.9rem + 0.6vw, 1.4rem);
				animation: rise 1.4s 0.15s cubic-bezier(0.2, 0.7, 0.2, 1) both;
			}

			.scrollhint {
				position: absolute;
				bottom: 2.5rem;
				font-size: 0.7rem;
				letter-spacing: 0.4em;
				text-transform: uppercase;
				color: var(--ink-soft);
				animation: breathe 3.5s ease-in-out infinite;
			}

			/* terraced ridges: parallax on scroll, pure CSS */
			.ridges {
				position: absolute;
				inset: auto 0 0 0;
				height: 70vh;
				z-index: -1;
				filter: blur(0.3px);
			}
			.ridges span {
				position: absolute;
				inset: auto -20% 0 -20%;
				border-radius: 50% 50% 0 0 / 22% 22% 0 0;
				background: var(--terrace);
			}
			.ridges span:nth-child(1) { height: 62%; opacity: 0.10; transform: translateY(2%); }
			.ridges span:nth-child(2) { height: 50%; opacity: 0.14; }
			.ridges span:nth-child(3) { height: 38%; opacity: 0.18; }
			.ridges span:nth-child(4) { height: 26%; opacity: 0.22; }
			.ridges span:nth-child(5) { height: 14%; opacity: 0.28; }

			/* ── sections ───────────────────────────────────────── */
			main { padding: 0 var(--gutter); }

			.chapter {
				max-width: 62rem;
				margin: 0 auto;
				padding: var(--rhythm) 0;
				border-top: 1px solid var(--rule);
			}
			.chapter.wide { max-width: 78rem; }

			.mark {
				font-family: var(--display);
				font-style: italic;
				color: var(--blossom-deep, var(--blossom));
				margin: 0 0 0.5rem;
			}
			@media (prefers-color-scheme: dark) { .mark { color: var(--blossom); } }

			.chapter h2, footer h2 {
				font-size: clamp(2.25rem, 1.5rem + 4vw, 5rem);
				line-height: 1;
				letter-spacing: -0.02em;
			}

			.line {
				max-width: 40ch;
				margin: 1rem 0 0;
				color: var(--ink-soft);
			}

			.grid {
				list-style: none;
				padding: 0;
				margin: clamp(2.5rem, 8vh, 5rem) 0 0;
				display: grid;
				gap: 1px;
				background: var(--rule);
				border: 1px solid var(--rule);
			}
			.craft { grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr)); }
			.work { grid-template-columns: repeat(auto-fit, minmax(17rem, 1fr)); }

			.grid li {
				background: var(--fog);
				padding: clamp(1.5rem, 3vw, 2.5rem);
				transition: background 0.5s ease;
			}
			.grid li:hover { background: color-mix(in oklab, var(--blossom) 14%, var(--fog)); }

			.grid h3 {
				font-size: 1.5rem;
				margin-bottom: 0.35rem;
			}
			.grid p { margin: 0; color: var(--ink-soft); font-size: 0.95rem; }

			.year {
				display: block;
				font-size: 0.7rem;
				letter-spacing: 0.3em;
				color: var(--moss);
				margin-bottom: 1.5rem;
			}

			.still { text-align: center; border-top: none; }
			blockquote {
				margin: 0 auto;
				max-width: 22ch;
				font-size: clamp(1.75rem, 1rem + 4vw, 3.75rem);
				line-height: 1.2;
				font-style: italic;
				color: var(--moss);
			}

			/* ── footer ─────────────────────────────────────────── */
			footer {
				padding: var(--rhythm) var(--gutter) clamp(3rem, 8vh, 6rem);
				background: var(--fog-deep);
				border-top: 1px solid var(--rule);
			}
			footer > * { max-width: 62rem; margin-inline: auto; }

			.cta {
				display: inline-block;
				margin-top: 2.5rem;
				font-family: var(--display);
				font-size: clamp(1.5rem, 1rem + 2vw, 2.5rem);
				color: var(--ink);
				text-decoration: none;
				border-bottom: 1px solid var(--blossom);
				padding-bottom: 0.15em;
				transition: border-color 0.4s, color 0.4s;
			}
			.cta:hover { color: var(--blossom-deep, var(--blossom)); border-color: currentColor; }

			.colophon {
				margin-top: clamp(4rem, 12vh, 8rem);
				font-size: 0.78rem;
				color: var(--ink-soft);
			}

			/* ── petals ─────────────────────────────────────────── */
			.petals { position: fixed; inset: 0; pointer-events: none; z-index: 2; }
			.petals span {
				position: absolute;
				top: -5vh;
				left: calc(var(--i) * 7.1% + 1%);
				width: 9px;
				height: 9px;
				background: var(--blossom);
				border-radius: 100% 0 100% 0;
				opacity: 0;
				animation: fall calc(14s + var(--i) * 1.7s) linear calc(var(--i) * -2.3s) infinite;
			}

			@keyframes fall {
				0%   { opacity: 0; transform: translate3d(0, 0, 0) rotate(0deg); }
				10%  { opacity: 0.7; }
				90%  { opacity: 0.5; }
				100% { opacity: 0; transform: translate3d(14vw, 105vh, 0) rotate(540deg); }
			}
			@keyframes rise {
				from { opacity: 0; transform: translateY(1.5rem); }
				to   { opacity: 1; transform: none; }
			}
			@keyframes breathe {
				0%, 100% { opacity: 0.35; }
				50%      { opacity: 0.9; }
			}

			/* ── scroll-driven motion (native, no JS) ───────────── */
			@keyframes reveal {
				from { opacity: 0; transform: translateY(2.5rem); }
				to   { opacity: 1; transform: none; }
			}
			@keyframes drift-up { to { transform: translateY(-18vh); } }
			@keyframes tint { to { background-color: color-mix(in oklab, var(--blossom) 8%, var(--fog)); } }

			@supports (animation-timeline: view()) {
				.chapter > *, footer > *, .grid li {
					animation: reveal linear both;
					animation-timeline: view();
					animation-range: entry 5% cover 26%;
				}
				.grid li { animation-range: entry 12% cover 34%; }

				.ridges span {
					animation: drift-up linear both;
					animation-timeline: scroll();
					animation-range: 0 100vh;
				}
				.ridges span:nth-child(2) { animation-range: 0 130vh; }
				.ridges span:nth-child(3) { animation-range: 0 170vh; }
				.ridges span:nth-child(4) { animation-range: 0 220vh; }
				.ridges span:nth-child(5) { animation-range: 0 290vh; }

				body {
					animation: tint linear both;
					animation-timeline: scroll();
					animation-range: 40vh 200vh;
				}
			}

			@media (prefers-reduced-motion: reduce) {
				html { scroll-behavior: auto; }
				*, *::before, *::after {
					animation: none !important;
					transition-duration: 0.01ms !important;
				}
				.petals { display: none; }
			}
		</style>
	</body>
</html>
